import java.util.Scanner;

public class Main {
    static final int MAXN = (1 << 19) | 5;
    static int n, k, p, maxn;
    static int[] popcount_arr = new int[MAXN];
    static int[] f_vals = new int[MAXN];
    static int[][] tmp1_arr = new int[20][MAXN];
    static int[][] tmp2_arr = new int[20][MAXN];
    static int[][] tmp3_arr = new int[20][MAXN];
    static long total_pow;
    static long[][] trans_arr = new long[20][MAXN];
    static long[] fact_arr = new long[MAXN];
    static long[] inv_fact_arr = new long[MAXN];

    static long bin_pow(long base, long exp) {
        long res = 1, cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * cur % p;
            cur = cur * cur % p;
            exp >>= 1;
        }
        return res;
    }

    static void prepare() {
        fact_arr[0] = 1;
        for (int i = 1; i <= maxn; i++)
            fact_arr[i] = fact_arr[i - 1] * i % p;
        inv_fact_arr[maxn] = bin_pow(fact_arr[maxn], p - 2);
        for (int i = maxn - 1; i >= 0; i--)
            inv_fact_arr[i] = inv_fact_arr[i + 1] * (i + 1) % p;
    }

    static int get_lower(int x) {
        int res = 1;
        while (res < x) res <<= 1;
        return res;
    }

    static void FWT(int[] arr, int len, boolean inv) {
        long[] temp = new long[len];
        for (int i = 0; i < len; i++) temp[i] = arr[i];
        for (int step = 1; step < len; step <<= 1) {
            for (int j = 0; j < len; j += (step << 1)) {
                for (int k = j; k < j + step; k++) {
                    long val = temp[k];
                    if (inv) {
                        temp[k + step] -= val;
                    } else {
                        temp[k + step] += val;
                    }
                }
            }
        }
        for (int i = 0; i < len; i++) {
            arr[i] = (int)((temp[i] % p + p) % p);
        }
    }

    static void mod_adjust(long[] x) {
        for (int i = 0; i < x.length; i++) {
            if (x[i] >= total_pow) x[i] -= total_pow;
        }
    }

    static void perform_multiplication() {
        for (int i = 0; i <= maxn; i++) {
            for (int j = 0; j < 20; j++) {
                tmp1_arr[j][i] = 0;
            }
        }
        for (int i = 0; i <= maxn; i++) {
            int c = popcount_arr[i];
            tmp1_arr[c][i] = f_vals[i];
        }
        for (int j = 0; j < 20; j++) {
            FWT(tmp1_arr[j], maxn + 1, false);
        }
        for (int q = 0; q <= 19; q++) {
            for (int l = 0; l + q <= 19; l++) {
                for (int s = 0; s <= maxn; s++) {
                    trans_arr[q + l][s] += 1L * tmp1_arr[q][s] * tmp2_arr[l][s];
                }
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= maxn; s++) {
                trans_arr[q][s] = ((trans_arr[q][s] % p) + p) % p;
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= maxn; s++) {
                tmp3_arr[q][s] = (int)(trans_arr[q][s] % p);
            }
        }
        for (int j = 0; j < 20; j++) {
            FWT(tmp3_arr[j], maxn + 1, true);
        }
        for (int j = 0; j <= maxn; j++) {
            int c = popcount_arr[j];
            f_vals[j] = tmp3_arr[c][j];
        }
    }

    static void perform_alt_multiplication() {
        long[][] temp = new long[20][MAXN];
        for (int i = 0; i < 20; i++) {
            for (int s = 0; s <= maxn; s++) {
                trans_arr[i][s] = 0;
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int l = 0; l + q <= 19; l++) {
                for (int s = 0; s <= maxn; s++) {
                    trans_arr[q + l][s] += 1L * tmp2_arr[q][s] * tmp2_arr[l][s];
                }
            }
        }
        for (int q = 0; q <= 19; q++) {
            for (int s = 0; s <= maxn; s++) {
                trans_arr[q][s] = ((trans_arr[q][s] % p) + p) % p;
            }
        }
        for (int i = 0; i < 20; i++) {
            for (int s = 0; s <= maxn; s++) {
                temp[i][s] = trans_arr[i][s];
            }
        }
        for (int i = 0; i < 20; i++) {
            FWT(temp[i], maxn + 1, true);
        }
        for (int i = 0; i < 20; i++) {
            for (int s = 0; s <= maxn; s++) {
                tmp2_arr[i][s] = 0;
            }
        }
        for (int i = 0; i <= maxn; i++) {
            int c = popcount_arr[i];
            tmp2_arr[c][i] = (int)temp[c][i];
        }
        for (int i = 0; i < 20; i++) {
            FWT(tmp2_arr[i], maxn + 1, false);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();
        total_pow = 1L * p * p;
        if ((n & 1) == 1) {
            System.out.println(bin_pow(k, n));
            sc.close();
            return;
        }
        f_vals[0] = 1;
        maxn = get_lower(n + 1) - 1;
        prepare();
        for (int i = 0; i <= maxn; i++) {
            popcount_arr[i] = Integer.bitCount(i);
        }
        for (int i = 0; i <= maxn; i++) {
            int c = popcount_arr[i];
            tmp2_arr[c][i] = (int)inv_fact_arr[i];
        }
        for (int i = 0; i < 20; i++) {
            FWT(tmp2_arr[i], maxn + 1, false);
        }
        int res_k = k;
        while (res_k > 0) {
            if ((res_k & 1) == 1) perform_multiplication();
            res_k >>= 1;
            if (res_k > 0) perform_alt_multiplication();
        }
        long result = (bin_pow(k, n) - fact_arr[n] * f_vals[n] % p + p) % p;
        System.out.println(result);
        sc.close();
    }
}

